using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            if (UnityEngine.SceneManagement.SceneManager.GetActiveScene().name != "CampusTerrain")
                EditorSceneManager.OpenScene("Assets/CampusSim/Scenes/CampusTerrain.unity");
            var p = new Vector3(-40.8f, -4, -321.4f);
            foreach (var r in Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None))
                if (Vector3.Distance(r.bounds.center, p) < 5)
                    result.Log(r.name + " parent=" + r.transform.parent?.name + " enabled=" + r.enabled + " material=" + r.sharedMaterial?.name);
        }
    }
}
